import { expect, it } from 'vitest'
import { decimal } from '@/services/quotationDecimal'
import { calculateLogisticsFee, type LogisticsRule } from './logistics'
import { normalizeLogisticsPriceRow } from './logisticsRepository'
import rows from './fixtures/wuyouBrazilRows.json'

// Four source rows generated by WuyouBrazilSourceTest from the actual 2026-10-10 workbook.
const rule: LogisticsRule = { id: 9001, name: '无忧物流-标准-巴西小包普货', englishName: '', type: '专线', currency: 'CNY',
  published: '', status: '启用', dates: '', users: '', relations: [], phoneRequired: false,
  areaCount: 1, priceRowCount: 4, billingVerified: false, prices: rows.map(normalizeLogisticsPriceRow) }
it('matches the independently specified source tariff at every gram and rounds fractional grams upward', () => {
  const rates=[68.26,81.92,81.92,89.36], fees=[29.01,32.01,34.01,35.01]
  for (let grams=1;grams<=2000;grams++) {
    const i=grams<=200?0:grams<=300?1:grams<=500?2:3
    const total=decimal(grams).div(1000).times(rates[i]!).plus(fees[i]!).toDecimalPlaces(2).toNumber()
    for(const weight of [grams/1000,(grams-.1)/1000])
      expect(calculateLogisticsFee(rule,'BR',weight,['普货']), `${grams}g/${weight}`).toMatchObject({chargeWeightKg:grams/1000,total})
  }
  expect(calculateLogisticsFee(rule,'BR',2.00001)).toBeNull()
  expect(calculateLogisticsFee(rule,'US',.1)).toBeNull()
  for(const mark of ['带电','化妆品','非液体化妆品','敏感货'])expect(calculateLogisticsFee(rule,'BR',.1,[mark])).toBeNull()
})
